def source(id,section=''):
 s=next(s for s in sources if s['id']==id)
 return f'<a class="citation" href="/sources/?id={id}">{esc(id)}{esc(" · "+section) if section else ""} ↗</a>'
def tag(s):return '<span class="tag '+('exact' if s.startswith('EXACT') else 'open' if s.startswith(('OPEN','CANDIDATE','NO-GO')) else '')+'">'+esc(s)+'</span>'
def block(num,title,body):return f'<section class="chapter"><div class="chapter-label">{num}</div><div><h2>{title}</h2>{body}</div></section>'
def intro(kicker,title,desc):return f'<div class="page-intro"><div class="eyebrow">{kicker}</div><h1>{title}</h1><p class="lede">{desc}</p></div>'
def eq(s):return f'<div class="equation">{s}</div>'
def callout(title,body):return f'<aside class="callout"><strong>{title}</strong><p>{body}</p></aside>'

