claim_html=''.join(f'<article class="claim" id="{id}"><div class="claim-top"><span class="mono">{id}</span>{tag(status)}</div><h3>{title}</h3><p class="premise">{ass}</p><div class="claim-result">{result}</div><p class="muted">{limit}</p>{source(sid,sec)}</article>' for id,title,status,ass,result,sid,sec,limit in claims)
pages['mathematics']=intro('Scoped results','The mathematical core.','Results are stated on declared carriers and metrics. A finite theorem retains its assumptions when it enters a larger programme.')+f'<div class="claims-grid">{claim_html}</div>'+block('08','One tetrahedron recurs. Glued carriers need not.',eq('eˢᴬ = P₀ + cos(2s)(I − P₀) + ½ sin(2s)A')+'<p>The filled-cell full-operator period is π in the declared internal parameter. K₋ and K₊ have incommensurate active frequencies; there is no finite common period for the full operator.</p><div class="comparison"><div><span>Δ³</span><b>2</b><small>one active frequency</small></div><div><span>K₋</span><b>√3, √5</b><small>two incommensurate frequencies</small></div><div><span>K₊</span><b>√2, √5</b><small>two incommensurate frequencies</small></div></div>'+source('PI','§§4.3, 6.4'))+block('09','Trace the coefficients.', '<p>The attached v0.39 ledger and later portal v0.65 file are preserved as distinct objects. Browse the later ledger’s 448 rows with their original bins, status, and next gates. A label in a source ledger is not new independent verification.</p><div class="actions"><a class="button" href="/ledger/">Inspect the typed ledger ↗</a><a class="text-link" href="/sources/?id=A20">Open historical v0.39 →</a></div>')

pages['dynamics']=intro('Evolution and its limits','What the equations move—and what they do not select.','A fixed-complex flow is explicit. Native event selection and cross-event interfaces are additional dynamical laws.')+block('01','The fixed-carrier baseline.', '<p>Declare K, signed B, unit metric, initial chain c(0) and the closed generator A. Then c(s) = exp(sA)c(0) is determined and its total support is conserved. The generator acts within one chain space; it does not choose a new complex, trigger a geometry event, or prescribe its state transfer.</p>'+source('PI','§§4, 7.4'))+block('02','A hard gate is a predicate, not an event clock.', eq('hₑ = Cₑ Tₑ &nbsp; · &nbsp; Cₑ,Tₑ ∈ {0,1}')+'<p>Closure and transport-integrity factors determine whether a supplied gate is open. Observing their product generally cannot identify which factor closed it. Under dynamics that depend only on the product, even all pre-event amplitude derivatives can leave the factor states indistinguishable.</p>'+source('R09','factor-state audit §§1–3')+source('A20','Q156–Q173')+callout('OPEN — source-selected transition','A predictive event needs typed pre-event inputs, an address, factor-update law, timing, admissibility and a tie rule. Counterfactual probes and hand-chosen thresholds remain candidate additions.'))+block('03','Event counts and time.', '<p>Scheduling by edge reversal on a bipartite vertex–cell incidence graph is a discrete counting programme. Relative heights and component offsets describe scheduling information. They do not supply a spacetime metric or a clock in seconds.</p><p>Likewise, an exact phase period in a matrix flow does not calibrate event duration. The current source catalog includes event-time manuscripts and LC bench/estimator records.</p>'+source('M01','items 5 and 7')+' <a class="text-link" href="/sources/?q=event%20time">Find event-time records →</a>')+block('04','Shape agreement, retention and growth.', '<div class="table-wrap"><table><thead><tr><th>Question</th><th>Required observation</th><th>Current boundary</th></tr></thead><tbody><tr><td>Coherent agreement</td><td>Declared compatibility at a snapshot</td><td>Does not imply persistence</td></tr><tr><td>Persistence</td><td>Retention over a specified interval and perturbation set</td><td>Prepared retention is conditional</td></tr><tr><td>Growth preference</td><td>Competing motifs under equal resources and admission rules</td><td>Native selection remains open</td></tr></tbody></table></div><p>Fresh-face attachment proves stacked-ball counts; both chain and star patterns remain possible. A nonregular icosahedral cone is a supplied construction, not evidence that regular tetrahedra universally select that shape.</p>'+source('PIII','§§11–12'))+block('05','Refinement has an interface cost.', '<p>The October 13 bounded-subdivision candidate transfers part of native support into a residual carrier. Its two-event support ledger is conditional. It does not preserve unit vertex readout or intertwine the unweighted native generators.</p>'+eq('native support: 1 → 5/8 → 25/64 &nbsp; · &nbsp; total with residuals: 1')+'<p>The strict interface contract—contraction, unit singleton vertex coefficient, and native-generator intertwining—fails on K₄ → sd K₄ because the incident degree changes from 3 to 7. Changing the readout, weights or event defect creates a new branch.</p>'+source('R33','bounded transfer §§2–4')+' '+source('R34','interface gate §2'))+block('06','Record entropy and retained information.', '<div id="information"></div><p>Record entropy depends on declared coarse-graining. Snapshot entropy need not increase; accumulated trajectory information is a different observable. Boundary-memory scaling requires an actual memory carrier and a full account of writing, storage, faults and renewal.</p><p>The October 13 receipt apparatus has a 34-slot decomposed write. A 44-slot deadline leaves 10 storage rounds; 32 rounds after writing require 66 total slots. The thermal-gap frontier is a requirement on candidate apparatus, not a native derivation of its gaps or temperature.</p>'+source('R36','session summary')+' '+source('R40','clock and non-identifiability')+callout('OPEN — full resource cost','Bath swaps export correlations. Controller, reservoir restoration, physical time, energy and area scales must be supplied before a complete efficiency or horizon-area correspondence is claimed.'))

pages['evidence']=intro('Evidence and physical correspondence','A bridge is a specific test.','No global physical identification is promoted. A mathematical agreement becomes a physical correspondence only through a declared map and independent evidence.')+callout('Physical promotion: 0','Finite proofs, exact replay, simulation, distribution and replication of an internal calculation have different evidentiary roles.')+block('01','The evidence ladder.', '<div class="ladder"><div><b>Internal mathematics</b><p>Proof or reproducible exact calculation on a declared carrier.</p></div><div><b>Candidate correspondence</b><p>Observable, measurement, units, calibration and uncertainty specified.</p></div><div><b>Frozen independent test</b><p>Inputs, baseline, exclusions and acceptance rule sealed before target exposure.</p></div><div><b>Replication and scoped ruling</b><p>Independent evaluation supports only the stated correspondence.</p></div></div><p>The supplied CRL-2 proposal distinguishes proposed, preregistered, executed and replicated measurement-facing objects. It requires a non-constructor review before advancement. The September 14 extension explicitly separates internal execution from measurement-facing CRL-2 execution.</p>'+source('A21','§§1–6')+' '+source('G14','§7.6'))+block('02','Current physical frontiers.', '<div class="table-wrap"><table><thead><tr><th>Frontier</th><th>Known boundary</th><th>Next discriminating input</th></tr></thead><tbody><tr><td>Pre-event polarity / POC-1</td><td>Frozen sidecar bytes and admissible native episode not recovered in the October 13 audit</td><td>Exact scorer archive plus independently authored, target-hidden native fixture</td></tr><tr><td>Lorentzian emergence</td><td>S₄ and preserved quadratic forms do not select a physical time direction</td><td>Source-selected refinement, principal symbol, common causal cone and clock map</td></tr><tr><td>Receipt entropy / area</td><td>Dimensionless errors do not identify physical area or energy cost</td><td>Native apparatus Hamiltonian, bath preparation, reset and geometric scale</td></tr><tr><td>LC operator bench</td><td>Prepared Stage 0 and estimator records; no measurement established here</td><td>Eligible calibrated capture and frozen comparison</td></tr><tr><td>Quadruple-tank correspondence</td><td>Delivered-flow source calibration and independent corpus are required</td><td>Source-authored calibration or directly measured pump flows</td></tr></tbody></table></div>'+source('R35','sidecar recovery')+' '+source('R29','signature gates')+' '+source('R40','source handoff')+' '+source('M01','items 7–8'))+block('03','What “replicated” means in one recorded case.', '<p>The portal records a Gemini replication and custodian CRL-2d ruling for the retained-parity carrier theorem: 12 in-scope passes and 6 failing controls. Its permanent rider is <em>transport consistency, not dynamical discovery</em>. This is source-recorded AI replication; it is not independent human review or a laboratory measurement.</p>'+source('GPAR')+' '+source('GREV'))+block('04','A physical bridge must expose its failure rule.', '<ul class="checklist"><li>Typed mathematical observable and physical measurement</li><li>Units, calibration map and uncertainty budget</li><li>Null or baseline comparison</li><li>Frozen prediction, exclusions and acceptance threshold</li><li>Target custody, independent evaluation and negative-result reporting</li></ul><p>A result that fails its frozen criterion stays failed. Exploratory reanalysis gets a new version and requires fresh independent evaluation for confirmatory use.</p>'+source('G14','source and exact-launch gates')+' '+source('PII','§§8–9'))+block('05','Applied programmes keep their own ledgers.', '<div class="route-grid"><a href="https://mqm-research.ben-w-mayes.chatgpt.site"><span>QUANTUM CONTROL</span><h3>MQM</h3><p>Fault-aware quantum-code and controller research. No hardware advantage is asserted here.</p><b>Separate programme ↗</b></a><a href="https://voxifold-systems.ben-w-mayes.chatgpt.site"><span>SPATIAL COMPUTE</span><h3>Lattix Systems</h3><p>Inspectable spatial compute. Equal-recall, equal-hardware benchmarking remains a separate gate.</p><b>Separate programme ↗</b></a><a href="/sources/?q=TetraDEC"><span>PHOTONICS</span><h3>TetraDEC</h3><p>Historical computational and engineering proposals. Performance claims need their own benchmark evidence.</p><b>Find source records →</b></a></div>'+source('M01','applied programme crosswalk'))

pages['papers']=intro('Primary reading','Four papers. Explicit claim boundaries.','Current review editions from the living portal, preserved with their versions. Publication distributes a result; it does not complete independent review.')+''.join(f'<article class="paper-row"><div class="paper-number">{p["roman"]}</div><div><span class="eyebrow">Paper {p["roman"]} · {p["version"][1:]}</span><h2>{p["topic"]}</h2><p>{next(s["title"] for s in sources if s["id"]=="P"+p["roman"])}</p><p class="muted">'+({'I':'Finite carriers, skew flow, unique-simplex gluing, spectra, ambient jumps and supplied readiness.','II':'Real and complex phase receipts, parity ambiguities, frozen-tree validation and covariance.','III':'Signed symmetry, radial shells, prepared shapes, burden, retention and collective mechanisms.','IV':'Finite apparatus, history clocks, capture windows, joint errors and correlation-preserving renewal.'}[p['roman']])+f'</p><div class="actions"><a class="button secondary" href="/papers/{p["name"]}.pdf">Read PDF ↗</a><a class="text-link" href="/sources/?id=P{p["roman"]}">Source and scope →</a><a class="text-link" href="/papers/{p["name"]}.md" download>Markdown ↓</a></div></div></article>' for p in papers)+block('05','Reproduction and review.', '<p>Every imported source retains its own constructor-check record. The new atlas additionally verifies three core incidence constructions with exact arithmetic; that check is limited to boundary identities, skew symmetry, spectra and simplex counts.</p><div class="actions"><a class="button" href="/sources/UD_ATLAS_CORE_VERIFICATION_v0.1.json">Atlas check receipt ↗</a><a class="text-link" href="/sources/verify_core.py" download>Exact checker ↓</a><a class="text-link" href="/papers/UD_Exact_Reproduction_v1.0_2026-09-16.zip" download>Earlier exact reproduction package ↓</a></div><p class="muted">The earlier v1.0 package is retained as an earlier replay object, not relabeled as a full verifier for the later papers.</p>')

pages['history']=intro('Lineage and corrections','Keep the past visible. Keep its status explicit.','Historical proposals explain how the programme developed. Their confidence language is not automatically inherited by the current presentation.')+block('01','The programme’s generations.', '<div class="timeline"><div><span>Early 2026</span><h3>Distinction Theory / Distinction Dynamics</h3><p>Packet-routing, seam holonomy, coherence, matter and cosmology proposals. Several supplied equation snapshots are placeholders.</p></div><div><span>May 2026</span><h3>Unified Dynamics v2.2–v2.3</h3><p>Broad parameter-free physics and capacity claims. Preserved as historical proposals pending a lawful source-to-measurement derivation.</p></div><div><span>August–September 2026</span><h3>Typed ledgers and finite-carrier audits</h3><p>Exact internal statements, conditional branches, no-gos and source gaps are separated.</p></div><div><span>October 2026</span><h3>Consolidated papers and source gates</h3><p>Review papers plus amendments on event eligibility, interfaces, signature and receipt resource costs.</p></div></div>'+source('S03')+' '+source('S04')+' '+source('A20')+' '+source('PI'))+block('02','Versioned dispositions.', '<div class="table-wrap"><table><thead><tr><th>Earlier statement</th><th>Current disposition</th><th>Reopening condition</th></tr></thead><tbody><tr><td>Equation pages / full repository supply complete derivations</td><td>9 standalone placeholders and 55 ZIP placeholders</td><td>Recover original equations and runnable sources</td></tr><tr><td>g = EδEᵀ derives Lorentzian spacetime for real E, positive δ</td><td>NO-GO on that carrier: the form is positive semidefinite</td><td>Source-derived hyperbolic co-metric on a separately typed carrier</td></tr><tr><td>Gap 2 gives a parameter-free measured spectral index</td><td>Historical report itself retains an undetermined n_CMB; replay unavailable</td><td>Original code/data, scale map and held-out evaluation</td></tr><tr><td>K₄ / S₄ counts derive Standard Model groups and measured constants</td><td>Historical physical identifications quarantined</td><td>Valid group/carrier map, dynamics, normalization and independent bridge</td></tr><tr><td>Later O45 ledger says sidecar not distributed</td><td>October 13 audit records conflicting later sent-message evidence; scorer bytes still missing</td><td>Preserve old row; consult amendment; recover original hash-matching bytes</td></tr><tr><td>34-slot write plus 32 storage rounds fits a 44-slot deadline</td><td>Correct schedule is 66 slots</td><td>Compare equal deadlines or equal storage ages explicitly</td></tr></tbody></table></div>'+source('A14','§§1, 4')+' '+source('R30','coframe conflict §3')+' '+source('R35','distribution conflict')+' '+source('R40','clock'))+block('03','Numbers retain their types.', '<p>7/768, 960/7, 1/(9π²), fitted spectral indices and the historical target 238.14 appear in older research. A count, a normalized ratio, a fitted parameter and a measured physical constant are different objects. Numerical agreement cannot supply the missing constitutive law or unit map.</p><p>The current ledger distinguishes exact internal objects, conditional results, candidates and frozen uses. The public atlas does not rederive a historical constant by backsolving its desired value.</p>'+source('S04','historical capacity and gauge claims')+' '+source('L65')+' '+source('M01','item 12'))+block('04','Original inputs remain recoverable.', '<p>The source registry includes every available attachment, both historical URLs, current portal records and the pinned GitHub file inventory. Raw notebooks are cataloged with hashes and scientific topics; internal and patent material is not republished. The missing genesis image remains an explicit intake gap.</p><a class="text-link" href="/sources/?group=Attached%20sources">Inspect the intake record →</a>')

pages['contribution']=intro('Contribution','Help make the next result checkable.','Mathematicians, scientists, independent peer reviewers and research software contributors are invited to take on a bounded task.')+block('01','Choose a concrete contribution.', '<div class="contribution-grid"><article><span class="eyebrow">MATHEMATICS</span><h3>Check a proof.</h3><p>Review one exact spectrum, reconstruction premise or interface obstruction. Identify missing steps and counterexamples.</p></article><article><span class="eyebrow">RESEARCH SOFTWARE</span><h3>Reproduce a calculation.</h3><p>Run a named replay in a fresh environment. Record the version, inputs, commands and differences.</p></article><article><span class="eyebrow">EXPERIMENTAL SCIENCE</span><h3>Qualify one bridge.</h3><p>Define the observable, measurement, calibration, custody and null comparison before exposure.</p></article><article><span class="eyebrow">SCIENTIFIC EDITING</span><h3>Repair a source chain.</h3><p>Recover an original equation, clarify units, improve notation or document a version conflict.</p></article></div>')+block('02','A useful first review.', '<ol class="checklist"><li>Name the artifact and version.</li><li>State the exact hypotheses and scope.</li><li>Return proof notes, a counterexample, code or a reproduction receipt.</li><li>Distinguish what passed from what remains unresolved.</li><li>Agree attribution and publication of the review summary.</li></ol><p>A review of one result does not endorse the whole framework. Reviewer compensation, if separately agreed, is for careful work regardless of conclusion.</p><div class="actions"><a class="button" href="https://github.com/ud-tetra/UD/issues/new">Offer a contribution on GitHub ↗</a><a class="text-link" href="https://github.com/ud-tetra/UD/blob/main/CONTRIBUTING.md">Contribution workflow →</a></div>')+block('03','Starter tasks with high information value.', '<div class="task-list"><div><b>01</b><p>Audit a declared A/B/C spectrum or fixed-mask continuity argument.</p></div><div><b>02</b><p>Review the receipt thermal-gap frontier, timing correction and dimensional non-identifiability proof.</p></div><div><b>03</b><p>Recover an original equation or scorer archive needed by a named open bridge.</p></div><div><b>04</b><p>Check the strict subdivision interface obstruction under its actual hypotheses.</p></div></div>')+block('04','Practical support.', '<p>Compute access, suitable equipment, hosting, and support for a separately agreed independent review can help. No payment is collected through this site. The contribution guide provides the current process for coordinating a task.</p>'+source('R41','public contribution guide'))

pages['updates']=intro('Updates and next work','A methodical consolidation.','Dated development notes live here. Current source versions, unresolved coverage and next gates stay visible.')+f'<div class="release-note"><span class="eyebrow">14 October 2026 UTC · Atlas 0.1</span><h2>A fresh public presentation layer</h2><p>Four review papers, 42 repository papers/reports, 977 searchable portal records, {len(portal_files):,} hashed portal files, 20 available attachments and a scientific memory crosswalk are connected in one navigation system.</p><p>This is an initial consolidated reading edition. Catalog coverage is broader than proof audit coverage. No scientific claim or physical correspondence is promoted by this release.</p><a class="text-link" href="/assets/coverage.json">Machine-readable coverage record ↓</a> · <a class="text-link" href="/releases/UD_PUBLIC_ATLAS_v0.1_RELEASE.zip" download>Download this reading edition ↓</a></div>'+block('01','Milestones and exit gates.', '<div class="table-wrap"><table><thead><tr><th>Stage</th><th>Exit criterion</th><th>Status</th></tr></thead><tbody><tr><td>1 · Source intake</td><td>Versions, hashes, coverage and missing inputs recorded</td><td>Complete for accessible sources</td></tr><tr><td>2 · Public foundation</td><td>Primer, results, dynamics, bridge limits and primary papers linked</td><td>Implemented in this edition</td></tr><tr><td>3 · Claim reconciliation</td><td>Every consequential historical assertion mapped to a current disposition and dependencies</td><td>Open; priority conflicts recorded</td></tr><tr><td>4 · Independent review</td><td>Non-constructor review of one bounded result recorded</td><td>Pending</td></tr><tr><td>5 · Physical evaluation</td><td>Eligible measurement passes its frozen independent bridge test</td><td>Pending</td></tr></tbody></table></div>')+block('02','Current development frontiers.', '<div class="news-list"><article><time>13 October 2026</time><h3>Receipt gap and common deadline</h3><p>34 write slots; 44 versus 66 total-slot comparisons. Dimensionless probability does not select physical energy or area.</p>'+source('R40')+'</article><article><time>13 October 2026</time><h3>Native signature and refinement</h3><p>Fixed-carrier skew flow does not choose a spatial refinement. Strict unit-readout/intertwining interface fails.</p>'+source('R29')+' '+source('R30')+' '+source('R34')+'</article><article><time>13 October 2026</time><h3>POC-1 custody gap</h3><p>Original sidecar bytes and eligible target-hidden native episode remain required before a score.</p>'+source('R35')+'</article><article><time>9–11 October 2026</time><h3>Predictive masks and typed event inputs</h3><p>Structural predicates, current observations and event source laws retain separate roles.</p>'+source('R09')+' '+source('R28')+'</article></div>')+block('03','The next public-edition priority.', '<p><strong>Reconcile the full claim/dependency register against October amendments.</strong> This prevents historical confidence labels from surviving in the presentation after their source has changed. Begin with physical identifications, source-selected event laws and complete resource costs.</p><p>Priority judgment: <strong>96/100</strong>. This score ranks expected progress and information value; it is not a measured closure percentage.</p>')+block('04','Coverage limitations.', '<ul class="checklist"><li>One missing image: Gap2_FINAL_Finite_Genesis.png.</li><li>Nine standalone equation placeholders and 55 placeholder archive entries.</li><li>Raw notebooks include internal/patent material; scientific topics are inventoried.</li><li>Memory crosswalk covers available project context, not all unexported conversations.</li><li>Archived source labels are searchable, but not automatically current.</li></ul><p>Core mathematical checks are exact constructor verification. Human review and physical evaluation remain separate gates. No numerical closure meter is invented.</p>')

pages['sources']=intro('Source registry','Follow every claim back to its object.','Search imported source text, versions and original labels. Filter by source family; open a document to inspect its provenance and full available text.')+f'<div class="inventory-banner"><div><b>20</b><span>available attachments</span></div><div><b>977</b><span>portal records</span></div><div><b>{len(portal_files):,}</b><span>hashed portal files</span></div><div><b>1</b><span>missing attachment</span></div></div><div class="search-tools"><label>Search sources<input type="search" id="source-query" placeholder="Try: entropy, Lorentzian, Q156, Paper II…"></label><label>Source family<select id="source-group"><option value="">All source families</option>'+''.join(f'<option>{g}</option>' for g in sorted(set(s['group'] for s in sources)))+'</select></label></div><div id="source-detail"></div><p id="result-count" class="muted" aria-live="polite"></p><div id="source-results"></div><div class="actions"><button class="button secondary" id="more-sources">Show more sources</button><a class="text-link" href="/assets/portal-file-inventory.json">Full hashed file inventory ↓</a></div><noscript><p>The interactive catalog requires JavaScript. <a href="/assets/sources.json">Download the full registry</a> or use the directly linked Papers.</p></noscript>'
pages['ledger']=intro('Typed coefficient register','Inspect the ledger without erasing its qualifiers.','The portal v0.65 source file contains 448 typed rows. Historical v0.39 is preserved separately. This view reproduces source bins, status and next gate; later amendments can narrow them.')+'<div class="search-tools"><label>Search ledger<input id="ledger-query" type="search" placeholder="ID, symbol, form, status or next gate…"></label><label>Claim bin<select id="ledger-bin"><option value="">All source bins</option>'+''.join(f'<option>{esc(k)}</option>' for k in sorted(set(r['claim_bin'] for r in ledger['rows'])))+'</select></label></div><p id="ledger-count" class="muted" aria-live="polite"></p><div id="ledger-results"></div>'+callout('Version metadata is retained','Filename release v0.65 is not substituted for its internal scientific-revision metadata. The full JSON includes both lineage and amendments. Read the original source before consequential reuse.')+source('L65')+' '+source('A20')

nav=[('home','Overview'),('primer','Primer'),('mathematics','Mathematics'),('dynamics','Dynamics'),('evidence','Evidence'),('papers','Papers'),('sources','Sources'),('history','History'),('contribution','Contribution'),('updates','Updates')]
for key,content in pages.items():
 title=dict(nav).get(key,'Typed ledger')
 nav_html=''.join(f'<a href="{("/" if k=="home" else "/"+k+"/")}" '+('aria-current="page"' if key==k else '')+f'><span>{i+1:02}</span>{v}</a>' for i,(k,v) in enumerate(nav))
 doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Unified Dynamics public research atlas: finite tetrahedral mathematics, declared dynamics, source provenance and independently testable physical questions."><meta name="theme-color" content="#f7f6ef"><title>{title} · Unified Dynamics</title><link rel="icon" href="/assets/icon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.css"><script src="/assets/app.js" defer></script></head><body data-page="{key}"><a class="skip" href="#main">Skip to content</a><aside class="sidebar"><a class="brand" href="/"><svg viewBox="0 0 40 40" aria-hidden="true"><path d="M20 3L3 33H37Z M20 3L22 23L3 33 M22 23L37 33"/></svg><div>Unified<br>Dynamics<small>PUBLIC RESEARCH ATLAS</small></div></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Explore <span>☰</span></button><nav id="navigation" aria-label="Primary">{nav_html}</nav><div class="sidebar-bottom"><span class="status-dot"></span> Physical promotion <b>0</b><p>Independent human review<br>pending</p><a href="{REPO}">Research repository ↗</a></div></aside><div class="page-shell"><header class="topbar"><span>FINITE STRUCTURE / OPEN CORRESPONDENCE</span><a href="/sources/">Search the record <span>⌕</span></a></header><main id="main">{content}</main><footer><div><a href="/">Unified Dynamics</a><p>Benjamin Walker Mayes · Independent researcher<br>AI-assisted research · Public reading edition 0.1</p></div><div><a href="/sources/">Sources & coverage</a><a href="/contribution/">Contribution</a><a href="{BASE}">Living research portal ↗</a></div><p class="footer-rule">Proof, simulation and physical correspondence retain distinct evidence status. Physical promotion: 0.</p></footer></div></body></html>'''
 out=DIST/'index.html' if key=='home' else DIST/key/'index.html';out.parent.mkdir(exist_ok=True);out.write_text(doc)

(DIST/'assets/icon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40"><rect width="40" height="40" fill="#f7f6ef"/><path d="M20 3L3 33H37Z M20 3L22 23L3 33 M22 23L37 33" fill="none" stroke="#244e42" stroke-width="2"/></svg>')
(DIST/'robots.txt').write_text('User-agent: *\nAllow: /\n')
(DIST/'sitemap.xml').write_text('<?xml version="1.0"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>https://unified-dynamics-public.ben-w-mayes.chatgpt.site'+('/' if k=='home' else '/'+k+'/')+'</loc></url>' for k in pages)+'</urlset>')
print(json.dumps(coverage))
